const ARROW = item(arrow, name: "&eСтраница")

when world_start {
    game list_goods = []
    for i in 1..50 { list_goods = append_value(set_item_name(item(paper), "Товар ${i}")) }
}

func open_list(page) {
    show_inventory_menu(name: "Товары, стр. ${page + 1}", custom_id: "list")
    expand_inventory_menu(size: 3)
    for i in 0..44 {
        n = page * 45 + i
        if n < len(list_goods) { set_inventory_menu_item(list_goods[n], i) }
    }
    if page > 0 { set_inventory_menu_item(set_item_custom_tag(ARROW, "page", page - 1), 45) }
    if (page + 1) * 45 < len(list_goods) { set_inventory_menu_item(set_item_custom_tag(ARROW, "page", page + 1), 53) }
}

when player_click_inventory {
    if value.open_inventory_custom_id != "list" { end_thread() }
    cancel_event()
    if item_has_tag(value.event_item, "page") { open_list(get_item_custom_tag(value.event_item, "page")) }
}

when player_chat {
    if chat_message_equals("@mi2") {
        cancel_event()
        open_list(0)
    }
}

