func remember_inventory() { save `kit_snapshot %player%` = value.inventory_items }

func restore_inventory() {
    clear_inventory()
    for slot, it in `kit_snapshot %player%` {
        if var.is_type(it, item) { set_slot_item(it, slot) }
    }
}

